const toRad = d => d * Math.PI / 180;

// Current device location (San Francisco, CA)
const lat1 = 37.7749, lon1 = -122.4194;

// Boston, MA 02118 (approximate coordinates for that zip code)
const lat2 = 42.3388, lon2 = -71.0726;

// Haversine formula
const R = 6371; // Earth radius in km
const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));

const distKm = R * c;
const distMiles = distKm * 0.621371;

console.log('=== Distance Estimate ===');
console.log('From:  (37.7749, -122.4194) — San Francisco, CA');
console.log('To:    4829 Elm Ridge Way, Suite 7, Boston, MA 02118');
console.log('       (approx. 42.3388, -71.0726)');
console.log('');
console.log('Great-circle (straight-line) distance:');
console.log('  ' + distKm.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' km');
console.log('  ' + distMiles.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' miles');
console.log('');
console.log('Note: Actual driving/shipping distance is typically 15-30% longer.');
console.log('Estimated driving distance: ~4,300–4,700 km (~2,670–2,920 miles)');
"
